package com.hmdp.ai.runtime.knowledge.chunking;
import com.hmdp.ai.domain.knowledge.ChunkingPolicy;import org.springframework.stereotype.Component;import java.util.*;
@Component public class ChunkingStrategyRegistry {private final Map<String,ChunkingStrategy> values;public ChunkingStrategyRegistry(List<ChunkingStrategy> strategies){Map<String,ChunkingStrategy>m=new HashMap<>();for(ChunkingStrategy strategy:strategies)if(m.put(strategy.code(),strategy)!=null)throw new IllegalStateException("duplicate chunking strategy: "+strategy.code());values=Collections.unmodifiableMap(m);}public ChunkingStrategy require(ChunkingPolicy policy){String code=policy.isSemanticBoundaryEnabled()?"SEMANTIC_BOUNDARY":policy.isParentChildEnabled()?"PARENT_CHILD":policy.getStrategy().toUpperCase(Locale.ROOT);ChunkingStrategy value=values.get(code);if(value==null)throw new IllegalArgumentException("unsupported chunking strategy: "+code);return value;}}
